VALUES('sirah_t4_p4',4,'Sirah','Pelajaran 4: Muslimatul Mujahidat',$sirahm4$[{"n":1,"title":"خديجة بنت خويلد","subtitle":"Latar belakang Sayidatina Khadijah","icon":"🌸","cards":[{"q":"نام بلياو اياله خديجة بنت خويلد رضي الله عنها.","a":"Nama beliau ialah Sayidatina Khadijah binti Khuwailid.","tip":"Nama beliau ialah Sayidatina Khadijah binti Khuwailid.","page":"84"},{"q":"خديجة اياله ايستري ڤرتام رسول الله ﷺ.","a":"Sayidatina Khadijah ialah isteri pertama Nabi Muhammad ﷺ.","tip":"Sayidatina Khadijah ialah isteri pertama Nabi Muhammad ﷺ.","page":"84"},{"q":"خديجة دڬلر ام المؤمنين.","a":"Khadijah dikenali sebagai salah seorang Ummahatul Mukminin, ibu orang beriman.","tip":"Khadijah dikenali sebagai salah seorang Ummahatul Mukminin, ibu orang beriman.","page":"84"},{"q":"خديجة براسل درڤد قوم قريش.","a":"Sayidatina Khadijah berasal daripada kaum Quraisy yang dihormati.","tip":"Sayidatina Khadijah berasal daripada kaum Quraisy yang dihormati.","page":"84"}]},{"n":2,"title":"كهنغت رما تڠݢ خديجة","subtitle":"Perkahwinan dan keluarga","icon":"🏡","cards":[{"q":"رسول الله ﷺ بركهوين دڠن خديجة كتيك اوسيا ٢٥ تاهون.","a":"Rasulullah ﷺ berkahwin dengan Khadijah ketika berumur 25 tahun.","tip":"Rasulullah ﷺ berkahwin dengan Khadijah ketika berumur 25 tahun.","page":"85"},{"q":"خديجة برعمر ٤٠ تاهون كتيك بركهوين.","a":"Buku teks menyatakan Khadijah berumur 40 tahun ketika berkahwin dengan Rasulullah ﷺ.","tip":"Buku teks menyatakan Khadijah berumur 40 tahun ketika berkahwin dengan Rasulullah ﷺ.","page":"85"},{"q":"خديجة مڠهارڬاءي دان مڽوكوڠ رسول الله ﷺ.","a":"Khadijah sentiasa menyokong dan membantu Rasulullah ﷺ.","tip":"Khadijah sentiasa menyokong dan membantu Rasulullah ﷺ.","page":"86–87"},{"q":"خديجة مڠأسوه دان مندديق انق دڠن بايق.","a":"Khadijah menjaga serta mendidik anak-anak dengan penuh kasih sayang.","tip":"Khadijah menjaga serta mendidik anak-anak dengan penuh kasih sayang.","page":"86"}]},{"n":3,"title":"اخلاق دان ڤرچوڠن خديجة","subtitle":"Sokongan dan pengorbanan Khadijah","icon":"💚","cards":[{"q":"خديجة اياله وانيتا ڤرتام مڠانوت اسلام.","a":"Khadijah merupakan wanita pertama yang memeluk Islam.","tip":"Khadijah merupakan wanita pertama yang memeluk Islam.","page":"86"},{"q":"خديجة مڽوكوڠ دعوه رسول الله ﷺ.","a":"Khadijah membantu Rasulullah ﷺ ketika baginda berdakwah.","tip":"Khadijah membantu Rasulullah ﷺ ketika baginda berdakwah.","page":"87"},{"q":"خديجة سڽنتياس مندوروڠ دان مڠهوبوركن هاتي رسول الله ﷺ.","a":"Khadijah memberi dorongan kepada Rasulullah ﷺ ketika menghadapi cabaran dakwah.","tip":"Khadijah memberi dorongan kepada Rasulullah ﷺ ketika menghadapi cabaran dakwah.","page":"87"},{"q":"خديجة برصيڤت صابر دالم مڠهادڤي اوجين.","a":"Khadijah menunjukkan sifat sabar menghadapi kesukaran perjuangan.","tip":"Khadijah menunjukkan sifat sabar menghadapi kesukaran perjuangan.","page":"86–87"}]},{"n":4,"title":"عائشة بنت ابي بكر","subtitle":"Latar belakang Sayidatina Aisyah","icon":"📜","cards":[{"q":"نام بلياو اياله عائشة بنت ابي بكر.","a":"Nama beliau ialah Sayidatina Aisyah binti Abu Bakar.","tip":"Nama beliau ialah Sayidatina Aisyah binti Abu Bakar.","page":"88"},{"q":"باڤا عائشة اياله ابو بكر الصديق.","a":"Aisyah ialah puteri Abu Bakar as-Siddiq.","tip":"Aisyah ialah puteri Abu Bakar as-Siddiq.","page":"88"},{"q":"ايبو عائشة اياله ام رومان بنت عامر.","a":"Ibu Aisyah bernama Ummu Ruman binti Amir.","tip":"Ibu Aisyah bernama Ummu Ruman binti Amir.","page":"88"},{"q":"عائشة دلاهيركن د مكة.","a":"Buku teks menyebut Aisyah dilahirkan di Makkah.","tip":"Buku teks menyebut Aisyah dilahirkan di Makkah.","page":"88"}]},{"n":5,"title":"اخلاق عائشة","subtitle":"Sabar, pemaaf dan mencintai Rasulullah","icon":"🕊️","cards":[{"q":"عائشة ممڤوڽاءي سيفت صابر.","a":"Sayidatina Aisyah memiliki sifat sabar ketika menghadapi cabaran.","tip":"Sayidatina Aisyah memiliki sifat sabar ketika menghadapi cabaran.","page":"89"},{"q":"عائشة سنتياس برصيفت ڤماعف.","a":"Buku teks menyatakan Aisyah seorang yang sentiasa memaafkan.","tip":"Buku teks menyatakan Aisyah seorang yang sentiasa memaafkan.","page":"89"},{"q":"عائشة مڠوتاماكن كسلامتن رسول الله ﷺ.","a":"Aisyah mengambil berat dan berusaha menjaga keselamatan Rasulullah ﷺ.","tip":"Aisyah mengambil berat dan berusaha menjaga keselamatan Rasulullah ﷺ.","page":"89"},{"q":"عائشة برصيڤت كوات حافظن.","a":"Aisyah memiliki daya ingatan yang kuat sebagaimana disenaraikan dalam carta akhlak buku teks.","tip":"Aisyah memiliki daya ingatan yang kuat sebagaimana disenaraikan dalam carta akhlak buku teks.","page":"89"}]},{"n":6,"title":"كعلموان عائشة","subtitle":"Ilmu, hadis dan pengajaran","icon":"📖","cards":[{"q":"عائشة تيڠڬي ڤڠتاهوان علمو حديث.","a":"Aisyah dikenali sebagai tokoh berilmu, terutama dalam bidang hadis.","tip":"Aisyah dikenali sebagai tokoh berilmu, terutama dalam bidang hadis.","page":"90"},{"q":"عائشة مريوايتكن ٢٢١٠ حديث.","a":"Buku teks menyatakan Aisyah meriwayatkan sebanyak 2,210 hadis.","tip":"Buku teks menyatakan Aisyah meriwayatkan sebanyak 2,210 hadis.","page":"90"},{"q":"عائشة منجادي تمڤت روجوقن اومت اسلام.","a":"Umat Islam merujuk Sayidatina Aisyah untuk mendapatkan ilmu hadis dan sunnah.","tip":"Umat Islam merujuk Sayidatina Aisyah untuk mendapatkan ilmu hadis dan sunnah.","page":"90"},{"q":"عائشة مڽمڤايكن حديث دڠن بتول.","a":"Aisyah membantu memelihara dan menyampaikan hadis Rasulullah ﷺ.","tip":"Aisyah membantu memelihara dan menyampaikan hadis Rasulullah ﷺ.","page":"90"}]}]$sirahm4$::jsonb,$sirahg4$[{"n":1,"name":"🌸 Latar belakang Sayidatina Khadijah","type":"clue","intro":"Jawab dalam Jawi dan semak berdasarkan buku teks.","steps":[["سياڤاكه نام ايستري ڤرتام رسول الله ﷺ؟",["خديجة بنت خويلد","عائشة بنت ابي بكر","حفصة بنت عمر","ام سلمة"],0,"Nama beliau ialah Sayidatina Khadijah binti Khuwailid.","84","🌸"],["خديجة منجادي ايستري كبراڤا رسول الله ﷺ؟",["كدوا","ڤرتام","كتيڬا","كاامڤت"],1,"Sayidatina Khadijah ialah isteri pertama Nabi Muhammad ﷺ.","84","🌸"],["اڤاكه ڬلرن خديجة رضي الله عنها؟",["ملك","اميرة","ام المؤمنين","ڤڽاير"],2,"Khadijah dikenali sebagai sa